-- WAVE DASH Supabase schema (RLS + server-validated RPC rewards; anon key client-side only)
create extension if not exists pgcrypto;
create table if not exists profiles(player_id uuid primary key default gen_random_uuid(),name text not null default 'Pilot',created_at timestamptz not null default now());
create table if not exists player_stats(player_id uuid primary key references profiles(player_id) on delete cascade,coins int not null default 0 check(coins>=0),diamonds int not null default 0 check(diamonds>=0),classic_stars int not null default 0 check(classic_stars>=0),rank_stars int not null default 0 check(rank_stars>=0),rank_tier text not null default 'Warrior',endless_best int not null default 0 check(endless_best>=0),challenge_clears int not null default 0 check(challenge_clears>=0),levels_completed int not null default 0 check(levels_completed>=0),updated_at timestamptz not null default now());
create table if not exists classic_progress(player_id uuid references profiles(player_id) on delete cascade,level_id int not null,best_score int not null default 0 check(best_score>=0),best_progress numeric(5,2) not null default 0 check(best_progress between 0 and 100),stars int not null default 0 check(stars between 0 and 3),completed boolean not null default false,updated_at timestamptz not null default now(),primary key(player_id,level_id));
create table if not exists rank_progress(player_id uuid references profiles(player_id) on delete cascade,level_id int not null,best_score int not null default 0 check(best_score>=0),stars int not null default 0 check(stars between 0 and 3),rank_stars_earned int not null default 0 check(rank_stars_earned>=0),completed boolean not null default false,updated_at timestamptz not null default now(),primary key(player_id,level_id));
create table if not exists time_trial_records(player_id uuid references profiles(player_id) on delete cascade,level_id int not null,best_time_ms int not null check(best_time_ms>0),attempts int not null default 1 check(attempts>0),updated_at timestamptz not null default now(),primary key(player_id,level_id));
create table if not exists challenge_progress(player_id uuid references profiles(player_id) on delete cascade,challenge_id text not null,cleared boolean not null default false,best_score int not null default 0 check(best_score>=0),best_time_ms int check(best_time_ms is null or best_time_ms>0),cleared_at timestamptz,primary key(player_id,challenge_id));
create table if not exists achievements(achievement_id text primary key,name text not null,description text,icon text,requirement_type text,requirement_value int,reward_coins int not null default 0 check(reward_coins>=0),reward_diamonds int not null default 0 check(reward_diamonds>=0),active boolean not null default true);
create table if not exists player_achievements(player_id uuid references profiles(player_id) on delete cascade,achievement_id text references achievements(achievement_id) on delete cascade,progress int not null default 0,unlocked boolean not null default false,claimed boolean not null default false,unlocked_at timestamptz,claimed_at timestamptz,primary key(player_id,achievement_id));
create table if not exists game_runs(id bigint generated always as identity primary key,player_id uuid references profiles(player_id) on delete cascade,mode text not null,level_id int,score int check(score>=0),time_ms int check(time_ms is null or time_ms>0),created_at timestamptz not null default now());
alter table profiles enable row level security; alter table player_stats enable row level security; alter table classic_progress enable row level security; alter table rank_progress enable row level security; alter table time_trial_records enable row level security; alter table challenge_progress enable row level security; alter table achievements enable row level security; alter table player_achievements enable row level security; alter table game_runs enable row level security;
create policy "pub profiles" on profiles for select using(true); create policy "pub stats" on player_stats for select using(true); create policy "pub ach" on achievements for select using(true);
create policy "own stats" on player_stats for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create policy "own classic" on classic_progress for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create policy "own rank" on rank_progress for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create policy "own trial" on time_trial_records for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create policy "own challenge" on challenge_progress for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create policy "own pa" on player_achievements for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create policy "own runs" on game_runs for all using(auth.uid()=player_id) with check(auth.uid()=player_id);
create or replace function submit_classic_result(p_level int,p_score int,p_progress numeric,p_stars int) returns void language plpgsql security definer as $$ begin if p_stars between 0 and 3 and coalesce(p_score,0)>=0 then insert into classic_progress(player_id,level_id,best_score,best_progress,stars,completed) values(auth.uid(),p_level,greatest(p_score,0),least(greatest(p_progress,0),100),p_stars,p_stars>0) on conflict(player_id,level_id) do update set best_score=greatest(classic_progress.best_score,excluded.best_score),best_progress=greatest(classic_progress.best_progress,excluded.best_progress),stars=greatest(classic_progress.stars,excluded.stars),completed=classic_progress.completed or excluded.completed,updated_at=now(); end if; end $$;
create or replace function submit_rank_result(p_level int,p_score int,p_stars int) returns void language plpgsql security definer as $$ begin if p_stars between 0 and 3 and coalesce(p_score,0)>=0 then insert into rank_progress(player_id,level_id,best_score,stars,rank_stars_earned,completed) values(auth.uid(),p_level,greatest(p_score,0),p_stars,p_stars,p_stars>0) on conflict(player_id,level_id) do update set best_score=greatest(rank_progress.best_score,excluded.best_score),stars=greatest(rank_progress.stars,excluded.stars),rank_stars_earned=greatest(rank_progress.rank_stars_earned,excluded.rank_stars_earned),completed=rank_progress.completed or excluded.completed,updated_at=now(); end if; end $$;
create or replace function submit_endless_result(p_score int) returns void language plpgsql security definer as $$ begin if coalesce(p_score,0)>=0 then insert into player_stats(player_id,endless_best) values(auth.uid(),greatest(p_score,0)) on conflict(player_id) do update set endless_best=greatest(player_stats.endless_best,excluded.endless_best),updated_at=now(); end if; end $$;
create or replace function submit_time_trial(p_level int,p_time_ms int) returns void language plpgsql security definer as $$ begin if coalesce(p_time_ms,0)>0 then insert into time_trial_records(player_id,level_id,best_time_ms) values(auth.uid(),p_level,p_time_ms) on conflict(player_id,level_id) do update set best_time_ms=least(time_trial_records.best_time_ms,excluded.best_time_ms),attempts=time_trial_records.attempts+1,updated_at=now(); end if; end $$;
create or replace function submit_challenge_result(p_challenge text,p_score int) returns void language plpgsql security definer as $$ begin if coalesce(p_score,0)>=0 then insert into challenge_progress(player_id,challenge_id,cleared,best_score,cleared_at) values(auth.uid(),p_challenge,true,greatest(p_score,0),now()) on conflict(player_id,challenge_id) do update set cleared=true,best_score=greatest(challenge_progress.best_score,excluded.best_score),cleared_at=now(); end if; end $$;
create or replace function claim_achievement_reward(p_achievement text) returns void language plpgsql security definer as $$ declare r record; begin select * into r from player_achievements where player_id=auth.uid() and achievement_id=p_achievement and unlocked and not claimed; if found then update player_achievements set claimed=true,claimed_at=now() where player_id=auth.uid() and achievement_id=p_achievement; update player_stats set coins=coins+coalesce((select reward_coins from achievements where achievement_id=p_achievement),0),diamonds=diamonds+coalesce((select reward_diamonds from achievements where achievement_id=p_achievement),0),updated_at=now() where player_id=auth.uid(); end if; end $$;
create or replace function get_rank_leaderboard() returns table(player_id uuid,name text,rank_tier text,rank_stars int) language sql security definer as $$ select p.player_id,p.name,s.rank_tier,s.rank_stars from player_stats s join profiles p using(player_id) order by s.rank_stars desc limit 100 $$;
create or replace function get_classic_leaderboard() returns table(player_id uuid,name text,classic_stars int) language sql security definer as $$ select p.player_id,p.name,s.classic_stars from player_stats s join profiles p using(player_id) order by s.classic_stars desc limit 100 $$;
create or replace function get_endless_leaderboard() returns table(player_id uuid,name text,endless_best int) language sql security definer as $$ select p.player_id,p.name,s.endless_best from player_stats s join profiles p using(player_id) order by s.endless_best desc limit 100 $$;
create or replace function get_time_trial_leaderboard() returns table(player_id uuid,name text,best_time_ms int) language sql security definer as $$ select p.player_id,p.name,min(t.best_time_ms) from time_trial_records t join profiles p using(player_id) group by p.player_id,p.name order by 3 asc limit 100 $$;
create or replace function get_challenge_leaderboard() returns table(player_id uuid,name text,challenge_clears int) language sql security definer as $$ select p.player_id,p.name,s.challenge_clears from player_stats s join profiles p using(player_id) order by s.challenge_clears desc limit 100 $$;
create or replace function get_coin_leaderboard() returns table(player_id uuid,name text,coins int) language sql security definer as $$ select p.player_id,p.name,s.coins from player_stats s join profiles p using(player_id) order by s.coins desc limit 100 $$;
create or replace function get_diamond_leaderboard() returns table(player_id uuid,name text,diamonds int) language sql security definer as $$ select p.player_id,p.name,s.diamonds from player_stats s join profiles p using(player_id) order by s.diamonds desc limit 100 $$;
